    exam: ['減数分裂の第一分裂で相同染色体が分かれ、染色体数が半減すること', '検定交雑の結果から組換え価を計算する', '3つの組換え価から遺伝子の並び順を決める（三点交雑）'],
    qs: [
      { q: '減数分裂の第一分裂前期に、相同染色体が対合したものを何という？', c: ['二価染色体', '姉妹染色分体', '紡錘体', '中心体'], e: '二価染色体は、4本の染色分体からなります。' },
      { q: '減数分裂で、染色体数が半分になるのはいつ？', c: ['第一分裂', '第二分裂', '間期の S 期', '受精のとき'], e: '第一分裂で相同染色体が分かれるので、2n から n になります。' },
      { q: '2n＝8 の生物で、配偶子の染色体の組合せは何通り？（乗換えは考えない）', c: ['16通り', '8通り', '4通り', '64通り'], e: '相同染色体は4対なので、2の4乗＝16通りです。' },
      { q: '乗換えが起こる時期はいつ？', c: ['第一分裂前期', '第一分裂後期', '第二分裂中期', '第二分裂終期'], e: '相同染色体が対合している第一分裂前期に起こります。' },
      { q: '同じ染色体上にあり、いっしょに配偶子に入りやすい遺伝子の関係を何という？', c: ['連鎖', '独立', '対立', '相補'], e: '連鎖している遺伝子は、乗換えが起こらなければいっしょに行動します。' },
      { q: 'AaBb を aabb と検定交雑し、［AB］8：［Ab］2：［aB］2：［ab］8 となった。組換え価は？', c: ['20％', '10％', '40％', '25％'], e: '(2＋2)÷(8＋2＋2＋8)×100＝20％ です。' },
      { q: 'AaBb の検定交雑で［AB］：［Ab］：［aB］：［ab］＝1：1：1：1 となった。A と B の関係は？', c: ['別々の染色体にあり独立している', '同じ染色体にあり完全に連鎖している', '同じ染色体のとても近くにある', '同じ遺伝子座の対立遺伝子である'], e: '独立していると、4種類の配偶子が同じ割合でできます。' },
      { q: '組換え価が大きい2つの遺伝子について正しいのは？', c: ['染色体上で離れている', '染色体上でとても近い', '別の生物に由来する', '必ず顕性である'], e: '離れているほど間で乗換えが起こりやすく、組換え価が大きくなります。' },
      { q: 'A-B 6％、A-C 4％、B-C 10％ のとき、まん中にある遺伝子は？', c: ['A', 'B', 'C', 'この値からは決められない'], e: 'いちばん大きい B-C の間に A があり、6＋4＝10 となり合います。' },
      { q: 'ショウジョウバエを使って、最初に染色体地図をつくった研究グループの中心人物は？', c: ['モーガン', 'メンデル', 'ダーウィン', 'ワトソン'], e: 'モーガンらは組換え価を使って遺伝子の位置を示しました。' }
    ],
    terms: [
      { w: '相同染色体', d: '父母から1本ずつ受けつぐ、形と大きさが同じ染色体の対' },
      { w: '二価染色体', d: '減数分裂で相同染色体が対合したもの' },
      { w: '乗換え', d: '対合した相同染色体の間で一部が交換されること' },
      { w: '組換え', d: '乗換えにより遺伝子の組合せが変わること' },
      { w: '連鎖', d: '複数の遺伝子が同じ染色体上にあること' },
      { w: '組換え価', d: '全配偶子のうち組換えの起きた配偶子の割合' },
      { w: '染色体地図', d: '遺伝子の並び順と相対的な距離を示した図' },
      { w: '検定交雑', d: '潜性ホモ接合体と交配して遺伝子型を調べる方法' }
    ]
